    assert bigrams("the quick quick brown") == {"the quick": 1, "quick quick": 1, "quick brown": 1}
    assert bigrams("a b a b a") == {"a b": 2, "b a": 2, "a b": 1}
    assert bigrams("hello") == {}
    assert bigrams("") == {}
    
