    try {
        // Test normal multiplication
        console.assert(multiplyMoney(100, 2) === 200, 'Test 1 failed: 100 * 2 should equal 200');
        console.assert(multiplyMoney(50, 0.5) === 25, 'Test 2 failed: 50 * 0.5 should equal 25');
        
