    # Test nested transactions
    store.begin()
    store.begin()
    store.set("key6", "value6", ttl=1)
    assert store.get("key6") == "value6"
    store.rollback()  # Rollback inner transaction
    assert store.get("key6") == "value6"  # Should still exist
